---@type CPacketHandlers
local handles = T(Global, "PacketHandlers")

function handles:SyncVoicePackData(packet)
    local player = PlayerManager:getClientPlayer()
    if not player.voicePackData then
        ---@type CVoicePackData
        local CVoicePackData = Plugins.Require("voice_pack", "client.data.c_voice_pack_data")
        player.voicePackData = CVoicePackData.new(player)
    end
    player.voicePackData:setVoices(packet.voices)
end